import Foundation
import XCTest
@testable import SecutgCore

/// PLAN.md 3.46: `vectors-security-audit.json`, generated by the Web reference
/// (`src/secutg/audit/vectors-security-audit.json`) and copied byte for byte — the same snapshot must give the same
/// findings, in the same order, on every client.
final class SecurityAuditVectorTests: XCTestCase {
    private lazy var vectors: [String: Any] = Vectors.load("vectors-security-audit")

    private func int64(_ raw: Any?) -> Int64? {
        guard let number = raw as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID() else { return nil }
        return number.int64Value
    }

    private func chat(_ raw: [String: Any]) -> SecurityAudit.Chat {
        return SecurityAudit.Chat(
            chatId: raw["chatId"] as? String ?? "",
            kind: SecurityAudit.ChatKind(rawValue: raw["kind"] as? String ?? "") ?? .privateChat,
            pairing: SecurityAudit.Pairing(rawValue: raw["pairing"] as? String ?? "") ?? .none,
            verified: raw["verified"] as? Bool ?? false,
            inviteReceived: raw["inviteReceived"] as? Bool ?? false,
            keyChangedInvite: raw["keyChangedInvite"] as? Bool ?? false,
            hasKey: raw["hasKey"] as? Bool ?? false,
            groupKeyCreatedMs: int64(raw["groupKeyCreatedMs"]),
            groupPasswordActive: raw["groupPasswordActive"] as? Bool ?? false,
            groupPasswordUnlocked: raw["groupPasswordUnlocked"] as? Bool ?? false,
            keyRequired: raw["keyRequired"] as? Bool,
            plaintextOnDisk: raw["plaintextOnDisk"] as? Bool ?? false,
            cloned: raw["cloned"] as? Bool ?? false)
    }

    private func snapshot(_ raw: [String: Any]) -> SecurityAudit.Snapshot {
        let settings = raw["settings"] as? [String: Any] ?? [:]
        let backup = raw["backup"] as? [String: Any] ?? [:]
        let version = raw["version"] as? [String: Any] ?? [:]
        let assistant = (raw["assistant"] as? [String: Any]).map { a in
            SecurityAudit.Assistant(enabled: a["enabled"] as? Bool ?? false, dataDir: a["dataDir"] as? String ?? "",
                                    serveConnected: a["serveConnected"] as? Bool ?? false,
                                    unconfirmedEvents: (a["unconfirmedEvents"] as? NSNumber)?.intValue ?? 0)
        }
        // PLAN.md 3.46.2: "field absent counts as null" — an old vector with no "account" key still passes.
        let accountRaw = raw["account"] as? [String: Any] ?? [:]
        let account = SecurityAudit.Account(
            twoStepPassword: accountRaw["twoStepPassword"] as? Bool,
            otherSessions: (accountRaw["otherSessions"] as? NSNumber)?.intValue)
        return SecurityAudit.Snapshot(
            chats: (raw["chats"] as? [[String: Any]] ?? []).map(chat),
            settings: SecurityAudit.Settings(
                groupKeyMaxAgeDays: (settings["groupKeyMaxAgeDays"] as? NSNumber)?.intValue ?? 0,
                localCiphertext: settings["localCiphertext"] as? Bool ?? false,
                wipePhraseSet: settings["wipePhraseSet"] as? Bool ?? false,
                wipeListens: settings["wipeListens"] as? Bool ?? false,
                netGateEnabled: settings["netGateEnabled"] as? Bool ?? false,
                apiCredentialSource: ApiCredentialRules.Source(rawValue: settings["apiCredentialSource"] as? String ?? "") ?? .none),
            lastBackupMs: int64(backup["lastBackupMs"]),
            lastKeyChangeMs: int64(backup["lastKeyChangeMs"]),
            ownVersion: version["own"] as? String,
            newestPeerSeen: version["newestPeerSeen"] as? String,
            assistant: assistant,
            account: account)
    }

    private func param(_ raw: Any) -> SecurityAudit.Param {
        if let number = raw as? NSNumber {
            return CFGetTypeID(number) == CFBooleanGetTypeID() ? .bool(number.boolValue) : .int(number.int64Value)
        }
        return .string(raw as? String ?? "")
    }

    private func finding(_ raw: [String: Any]) -> SecurityAudit.Finding {
        return SecurityAudit.Finding(
            id: raw["id"] as? String ?? "",
            check: (raw["check"] as? NSNumber)?.intValue ?? 0,
            level: SecurityAudit.Level(rawValue: raw["level"] as? String ?? "") ?? .ok,
            chatId: raw["chatId"] as? String,
            params: (raw["params"] as? [String: Any] ?? [:]).mapValues(param),
            action: SecurityAudit.Action(rawValue: raw["action"] as? String ?? "") ?? .none)
    }

    func testFormat() {
        XCTAssertEqual(vectors["format"] as? String, "secutg-security-audit-vectors/1")
    }

    func testEveryCase() {
        let cases = vectors["cases"] as? [[String: Any]] ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 40, "the vector file lost cases")
        for item in cases {
            let name = item["name"] as? String ?? "?"
            let ignored = (item["ignored"] as? [String: Any] ?? [:]).compactMapValues(int64)
            let nowMs = int64(item["now_ms"]) ?? 0
            let expect = item["expect"] as? [String: Any] ?? [:]
            let findings = SecurityAudit.run(snapshot(item["snapshot"] as? [String: Any] ?? [:]), nowMs: nowMs, ignored: ignored)
            let expected = (expect["findings"] as? [[String: Any]] ?? []).map(finding)
            XCTAssertEqual(findings.map { $0.id }, expected.map { $0.id }, "\(name): ids / order")
            XCTAssertEqual(findings, expected, name)
            let summary = expect["summary"] as? [String: NSNumber] ?? [:]
            XCTAssertEqual(SecurityAudit.summarize(findings),
                           SecurityAudit.Summary(risk: summary["risk"]?.intValue ?? -1, warn: summary["warn"]?.intValue ?? -1, ok: summary["ok"]?.intValue ?? -1),
                           "\(name): summary")
        }
    }

    /// Every check 1–11 shows each level at least once across the file, except check 6's risk (none by design) —
    /// computed from what `SecurityAudit.run` produces, not from the file's expectations.
    func testCoverage() {
        let cases = vectors["cases"] as? [[String: Any]] ?? []
        var seen = Set<String>()
        for item in cases {
            let nowMs = int64(item["now_ms"]) ?? 0
            for f in SecurityAudit.run(snapshot(item["snapshot"] as? [String: Any] ?? [:]), nowMs: nowMs) {
                seen.insert("\(f.check):\(f.level.rawValue)")
            }
        }
        for check in 1...13 {
            for level in ["ok", "warn", "risk"]
            where !(check == 6 && level == "risk") && !(check == 12 && level == "warn") && !(check == 13 && level == "risk") {
                XCTAssertTrue(seen.contains("\(check):\(level)"), "no vector shows \(check):\(level)")
            }
        }
    }

    private func combined() -> [String: Any] {
        let cases = vectors["cases"] as? [[String: Any]] ?? []
        return cases.first { ($0["name"] as? String ?? "").hasPrefix("combined") } ?? [:]
    }

    /// The output is sorted by the shared comparator whatever order the chats come in (Web's property test).
    func testOrderDoesNotDependOnChatOrder() {
        let item = combined()
        var raw = item["snapshot"] as? [String: Any] ?? [:]
        raw["chats"] = Array((raw["chats"] as? [[String: Any]] ?? []).reversed())
        let ignored = (item["ignored"] as? [String: Any] ?? [:]).compactMapValues(int64)
        let findings = SecurityAudit.run(snapshot(raw), nowMs: int64(item["now_ms"]) ?? 0, ignored: ignored)
        let expected = ((item["expect"] as? [String: Any])?["findings"] as? [[String: Any]] ?? []).map(finding)
        XCTAssertFalse(expected.isEmpty)
        XCTAssertEqual(findings, expected)
    }

    /// A non-positive N falls back to 90 days.
    func testNonPositiveGroupKeyLimitFallsBackTo90() {
        let item = combined()
        var raw = item["snapshot"] as? [String: Any] ?? [:]
        var settings = raw["settings"] as? [String: Any] ?? [:]
        for n in [0, -3] {
            settings["groupKeyMaxAgeDays"] = n
            raw["settings"] = settings
            let group = SecurityAudit.run(snapshot(raw), nowMs: int64(item["now_ms"]) ?? 0).first { $0.check == 3 && $0.chatId == "-910" }
            XCTAssertEqual(group?.params["limit"], .int(90), "N = \(n)")
        }
    }
}
